contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint val1, uint val2) public {
        require(val1 != val2);
        c.SetMinSum(val1);
        assert(c.MinSum() == val1);
        c.Initialized();
        bool reverted;
        try c.SetMinSum(val2) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.MinSum() == val1);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint minSum1, uint minSum2, bool doInit) public payable {
        require(minSum1 != minSum2);
        c.SetMinSum(minSum1);
        bool revertedMinSum;
        bool revertedLogFile;
        if (doInit) {
            c.Initialized();
            try c.SetMinSum(minSum2) { revertedMinSum = false; } catch { revertedMinSum = true; }
            try c.SetLogFile(address(0)) { revertedLogFile = false; } catch { revertedLogFile = true; }
            assert(revertedMinSum && revertedLogFile && c.MinSum() == minSum1);
        } else {
            c.SetMinSum(minSum2);
            assert(!doInit && c.MinSum() == minSum2);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint dep, uint am, uint amount) public payable {
        require(dep >= am);
        c.Deposit{value: dep}();
        uint balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        c.Collect{value: amount}(am);
        uint balAfter = c.balances(address(this));
        uint ethAfter = address(c).balance;
        assert(balBefore - balAfter == am && ethBefore + amount >= ethAfter && (ethBefore + amount) - ethAfter == am);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    bool rejectEther;

    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        c.Deposit{value: amount}();
        uint depBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;

        rejectEther = true;
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        rejectEther = false;

        assert(reverted && c.balances(address(this)) == depBefore && address(c).balance == ethBefore);
    }

    receive() external payable {
        if (rejectEther) { revert(); }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint minSum, uint deposit, uint am) public payable {
        require(address(this).balance >= deposit);

        c.SetMinSum(minSum);
        c.Deposit{value: deposit}();

        uint depBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        uint minSumBefore = c.MinSum();

        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }

        bool checksPass = (depBefore >= minSumBefore) && (depBefore >= am);
        assert(
            c.balances(address(this)) == depBefore &&
            address(c).balance == ethBefore &&
            reverted == checksPass
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint v1, uint v2) public payable {
        require(address(this).balance >= v1 + v2);

        c.Deposit{value: v1}();
        bool recvReverted;
        // send v2 directly to trigger receive(), which must credit it as a deposit
        (bool ok, ) = address(c).call{value: v2}("");
        recvReverted = !ok;

        uint recorded = c.balances(address(this));
        uint contractEth = address(c).balance;

        assert(
            !recvReverted &&
            recorded == v1 + v2 &&
            contractEth == v1 + v2
        );
    }

    receive() external payable {}
}

