contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C();
    }

    function _run(uint256 v, uint256 a1, uint256 a2) internal {
        v = bound(v, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(v > 0);
        vm.assume(a1 + a2 <= v);
        vm.assume(a1 <= v && a2 <= v);
        vm.assume(address(this).balance >= v);
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(0) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: v}() {} catch { return; }
        uint256 recorded;
        try c.balances(address(this)) returns (uint256 __r) { recorded = __r; } catch { return; }
        v = recorded;
        v = address(c).balance;
        try c.Collect(a1) {} catch { return; }
        try c.Collect(a2) {} catch { return; }
        assertTrue(c.balances(address(this)) == v - a1 - a2 &&
            address(c).balance == v - a1 - a2);
    }

    function testFuzz_run(uint256 v, uint256 a1, uint256 a2) public {
        _run(v, a1, a2);
    }

    receive() external payable { }

    fallback() external payable { }
}
